//! A household of the shared portfolio's two accounts against an independent implementation in
//! pandas and SciPy. The fixture is generated by `scripts/reference/households.py`.

#![allow(clippy::unwrap_used)]

use finalytics::formats::{CsvOptions, fx_from_csv, portfolio_from_csv, prices_from_csv};
use finalytics::{
    AccountsPerformance, Books, Currency, Date, HouseholdOptions, MarketData, household,
};
use serde_json::Value;

const ACCOUNTS: &str = include_str!("../../../tests/scenario/accounts.csv");
const INSTRUMENTS: &str = include_str!("../../../tests/scenario/instruments.csv");
const TRANSACTIONS: &str = include_str!("../../../tests/scenario/transactions.csv");
const PRICES: &str = include_str!("../../../tests/scenario/prices.csv");
const FX: &str = include_str!("../../../tests/scenario/fx.csv");

fn setup() -> (Books, MarketData) {
    let options = CsvOptions::default();
    let portfolio = portfolio_from_csv(
        Currency::USD,
        INSTRUMENTS,
        TRANSACTIONS,
        Some(ACCOUNTS),
        options,
    )
    .unwrap();
    let mut market = MarketData::new();
    for (id, prices) in prices_from_csv(PRICES, options).unwrap() {
        market = market.with_prices(id, prices);
    }
    for fx in fx_from_csv(FX, options).unwrap() {
        market = market.with_fx(fx.base, fx.quote, fx.rates);
    }
    (Books::build(&portfolio, &market).unwrap(), market)
}

#[track_caller]
fn close(actual: f64, expected: &Value, tolerance: f64, what: &str) {
    let expected = expected.as_f64().unwrap();
    assert!(
        (actual - expected).abs() <= tolerance * expected.abs().max(1.0),
        "{what}: {actual} against the reference {expected}"
    );
}

fn compare(found: &AccountsPerformance, expected: &Value) {
    let name = &found.name;
    let accounts: Vec<&str> = found.accounts.iter().map(|a| a.as_str()).collect();
    let listed: Vec<&str> = expected["accounts"]
        .as_array()
        .unwrap()
        .iter()
        .map(|a| a.as_str().unwrap())
        .collect();
    assert_eq!(accounts, listed, "{name}");
    close(found.value_start, &expected["value_start"], 1e-12, name);
    close(found.value_end, &expected["value_end"], 1e-12, name);
    close(found.flows, &expected["flows"], 1e-12, name);
    let twr = found.time_weighted.unwrap();
    close(
        twr,
        &expected["time_weighted"],
        1e-12,
        &format!("{name} time-weighted"),
    );
    let mwr = found.money_weighted.unwrap();
    close(
        mwr,
        &expected["money_weighted"],
        1e-10,
        &format!("{name} money-weighted"),
    );
    close(
        found.contribution,
        &expected["contribution"],
        1e-12,
        &format!("{name} contribution"),
    );
}

#[test]
fn a_household_matches_the_reference() {
    let (books, market) = setup();
    let f: Value = serde_json::from_str(include_str!("fixtures/households.json")).unwrap();
    let dates: Vec<Date> = f["dates"]
        .as_array()
        .unwrap()
        .iter()
        .map(|d| d.as_str().unwrap().parse().unwrap())
        .collect();
    let mut options = HouseholdOptions::default();
    options.group_by = vec!["owner".into(), "wrapper".into()];
    let h = household(&books, &market, &dates, &options).unwrap();
    compare(&h.household, &f["household"]);
    let accounts = f["accounts"].as_array().unwrap();
    assert_eq!(h.accounts.len(), accounts.len());
    for (found, expected) in h.accounts.iter().zip(accounts) {
        assert_eq!(found.name, expected["name"].as_str().unwrap());
        compare(found, expected);
    }
    for scheme in &h.groups {
        let groups = f["groups"][&scheme.scheme].as_array().unwrap();
        assert_eq!(scheme.groups.len(), groups.len());
        for (found, expected) in scheme.groups.iter().zip(groups) {
            assert_eq!(found.name, expected["name"].as_str().unwrap());
            compare(found, expected);
        }
    }
    let total: f64 = h.accounts.iter().map(|a| a.contribution).sum();
    assert!((total - h.household.time_weighted.unwrap()).abs() < 1e-15);
}
